class Solution {public:vector<long long> solve(long long aNum,long long aDen,long long bNum,long long bDen,string operation){long long n,d;if(operation=="+"||operation=="-"){n=aNum*bDen+(operation=="+"?bNum:-bNum)*aDen;d=aDen*bDen;}else if(operation=="*"){n=aNum*bNum;d=aDen*bDen;}else{n=aNum*bDen;d=aDen*bNum;}if(d<0){n=-n;d=-d;}long long x=llabs(n),y=d;while(y){long long t=x%y;x=y;y=t;}return {n/x,d/x};}};